const lockSquadWorkflowTemplateAgents = `-- name: LockSquadWorkflowTemplateAgents :many
SELECT agent.id
FROM agent
JOIN squad_member
  ON squad_member.member_id = agent.id
 AND squad_member.member_type = 'agent'
WHERE agent.workspace_id = $1
  AND agent.archived_at IS NULL
  AND squad_member.squad_id = $2
  AND agent.id = ANY($3::uuid[])
ORDER BY agent.id
FOR KEY SHARE OF agent, squad_member
`

type LockSquadWorkflowTemplateAgentsParams struct {
	WorkspaceID pgtype.UUID   `json:"workspace_id"`
	SquadID     pgtype.UUID   `json:"squad_id"`
	AgentIds    []pgtype.UUID `json:"agent_ids"`
}

func (q *Queries) LockSquadWorkflowTemplateAgents(ctx context.Context, arg LockSquadWorkflowTemplateAgentsParams) ([]pgtype.UUID, error) {
	rows, err := q.db.Query(ctx, lockSquadWorkflowTemplateAgents, arg.WorkspaceID, arg.SquadID, arg.AgentIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []pgtype.UUID{}
	for rows.Next() {
		var id pgtype.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

